let j = null;
// a IA às vezes escreve "inicio": 14.9s (copiando o formato das cenas) — tira o "s" para o JSON valer
const bruto = String($('🤖 Roteirista').first().json.output || '').replace(/("inicio"\s*:\s*)(\d+)(?:[.,](\d+))?\s*s\b/g, (m, a, i, d) => a + i + (d ? '.' + d : ''));
try { j = parseJSON(bruto); } catch (e) {}
// plano B: JSON quebrado? pega cada trecho "inicio ... texto" pelo padrão
if (!j || !Array.isArray(j.segmentos)) {
  const achados = [...bruto.matchAll(/"inicio"\s*:\s*"?(\d+(?:[.,]\d+)?)[^"]*?"texto"\s*:\s*"((?:[^"\\]|\\.)*)"/g)].map(m => ({ inicio: Number(m[1].replace(',', '.')), texto: m[2].replace(/\\"/g, '"') }));
  const tit = (bruto.match(/"titulo"\s*:\s*"((?:[^"\\]|\\.)*)"/) || [])[1] || '';
  if (achados.length) j = { titulo: tit, segmentos: achados };
}
const limpa = s => String(s ?? '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}*#_<>]/gu, '').replace(/\s+/g, ' ').trim();
const segs = (j && Array.isArray(j.segmentos) ? j.segmentos : []).map((s, i) => ({
  n: i + 1, inicio: Math.max(0, Math.min(Number(s.inicio) || 0, Math.max(0, dur - 2))), texto: limpa(s.texto).slice(0, 400),
})).filter(s => s.texto.split(' ').length >= 3).slice(0, 30);
segs.forEach((s, i) => { s.n = i + 1; });
if (segs.length < 2) return [{ json: { ok: false, erro: 'A IA roteirista não devolveu um roteiro válido. Tente de novo.' } }];
return [{ json: { ok: true, titulo: limpa(j.titulo).slice(0, 60), segmentos: segs, palavras: segs.reduce((n, s) => n + s.texto.split(' ').length, 0) } }];

