// Junta o roteiro com as escolhas do diretor de edição (efeito e transição de cada trecho) e o texto de SEO.
const v = $('🧩 Confere o pedido').first().json;
const rot = $('🧩 Confere o roteiro').first().json;
let dir = null, seo = null;
try { dir = parseJSON($('🤖 Diretor de edição').first().json.output); } catch (e) {}
try { seo = parseJSON($('🤖 Especialista em SEO').first().json.output); } catch (e) {}
const EFEITOS = ['nenhum', 'zoom_in', 'zoom_out', 'tremor', 'flash', 'pb', 'lento'];
const TRANS = ['fade', 'fadeblack', 'fadewhite', 'wipeleft', 'wiperight', 'slideleft', 'slideright', 'circleopen', 'circleclose', 'radial', 'pixelize', 'dissolve', 'smoothleft', 'smoothright', 'zoomin', 'hblur', 'distance', 'diagtl', 'squeezeh'];
const reserva = ['zoom_in', 'nenhum', 'zoom_out', 'flash', 'nenhum', 'tremor'];
const transReserva = ['fade', 'slideleft', 'fadeblack', 'circleopen', 'wipeleft', 'dissolve', 'radial'];
const plano = dir && Array.isArray(dir.segmentos) ? dir.segmentos : [];
const segmentos = rot.segmentos.map((s, i) => {
  const p = plano.find(x => Number(x.n) === s.n) || {};
  return { ...s, efeito: EFEITOS.includes(p.efeito) ? p.efeito : reserva[i % reserva.length], transicao: TRANS.includes(p.transicao) ? p.transicao : transReserva[i % transReserva.length] };
});
const txt = (s, m) => String(s ?? '').replace(/[<>{}\\]/g, '').trim().slice(0, m);
const titulo = v.op.titulo || txt(dir && dir.titulo_abertura, 50) || rot.titulo;
const cta = v.op.cta || txt(dir && dir.cta, 40) || (v.op.idioma === 'pt' ? 'Siga para mais!' : v.op.idioma === 'es' ? '¡Sígueme para más!' : 'Follow for more!');
const SEO = seo ? { titulo: txt(seo.titulo, 100), descricao: txt(seo.descricao, 900), tags: (Array.isArray(seo.tags) ? seo.tags : []).map(t => txt(t, 40)).slice(0, 15),
  hashtags: (Array.isArray(seo.hashtags) ? seo.hashtags : []).map(t => '#' + String(t).replace(/[^\p{L}\p{N}_]/gu, '')).slice(0, 5) } : null;
return [{ json: { segmentos, titulo, cta, seo: SEO,
  narrar: JSON.stringify({ job: v.job, voz: v.op.voz, segmentos: segmentos.map(s => ({ n: s.n, texto: s.texto })) }) } }];

